from itertools import product
from typing import Callable, List

BinOp = Callable[[int, int], int]

def is_two_sided_unit(op: BinOp, elems: List[int], unit: int) -> bool:
    return all(op(unit, a) == a and op(a, unit) == a for a in elems)

def satisfies_interchange(vcomp: BinOp, hcomp: BinOp, elems: List[int]) -> bool:
    for a, b, c, d in product(elems, repeat=4):
        if vcomp(hcomp(a, b), hcomp(c, d)) != hcomp(vcomp(a, c), vcomp(b, d)):
            return False
    return True

def audit(vcomp: BinOp, hcomp: BinOp, elems: List[int], unit: int) -> dict:
    valid = (is_two_sided_unit(vcomp, elems, unit)
             and is_two_sided_unit(hcomp, elems, unit)
             and satisfies_interchange(vcomp, hcomp, elems))
    coincide = all(vcomp(a, b) == hcomp(a, b) for a in elems for b in elems)
    comm = all(vcomp(a, b) == vcomp(b, a) for a in elems for b in elems)
    assoc = all(vcomp(vcomp(a, b), c) == vcomp(a, vcomp(b, c))
                for a in elems for b in elems for c in elems)
    return {"valid_structure": valid, "operations_coincide": coincide,
            "commutative": comm, "associative": assoc}

if __name__ == "__main__":
    for m in (3, 4, 6):
        elems = list(range(m))
        add: BinOp = lambda a, b, m=m: (a + b) % m
        print(f"Z/{m}:", audit(add, add, elems, 0))

from itertools import product
from typing import Callable, List, Tuple

BinOp = Callable[[int, int], int]

def to_pair(n: int) -> Tuple[int, int]:
    return (n // 2, n % 2)

def of_pair(p: Tuple[int, int]) -> int:
    return 2 * (p[0] % 2) + (p[1] % 2)

def vcomp(a: int, b: int) -> int:
    (x1, y1), (x2, y2) = to_pair(a), to_pair(b)
    return of_pair((x1 + x2, y1 + y2))

def hcomp(a: int, b: int) -> int:
    (x1, y1), (x2, y2) = to_pair(a), to_pair(b)
    return of_pair((x2 + x1, y2 + y1))

def interchange_holds(elems: List[int]) -> bool:
    return all(vcomp(hcomp(a, b), hcomp(c, d)) == hcomp(vcomp(a, c), vcomp(b, d))
               for a, b, c, d in product(elems, repeat=4))

if __name__ == "__main__":
    elems = list(range(4))
    print("interchange holds:", interchange_holds(elems))
    print("tables identical:",
          all(vcomp(a, b) == hcomp(a, b) for a in elems for b in elems))
    print("vcomp table:")
    for a in elems:
        print("  ", [vcomp(a, b) for b in elems])

from itertools import product
from typing import Callable, List

BinOp = Callable[[int, int], int]

def satisfies_interchange(v: BinOp, h: BinOp, e: List[int]) -> bool:
    return all(v(h(a, b), h(c, d)) == h(v(a, c), v(b, d))
               for a, b, c, d in product(e, repeat=4))

def is_commutative(op: BinOp, e: List[int]) -> bool:
    return all(op(a, b) == op(b, a) for a in e for b in e)

if __name__ == "__main__":
    elems = [0, 1, 2]
    # Left projection has no shared unit; theorem's hypotheses fail.
    left: BinOp = lambda a, b: a
    print("left-projection interchange with itself:",
          satisfies_interchange(left, left, elems))
    print("left-projection commutative:", is_commutative(left, elems))
    print("=> A non-commutative operation cannot arise from a valid",
          "interchange structure, confirming both hypotheses are essential.")

